'use client'
/** Home: the MATRIX card `home-clock`. Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { henryBoard } from '@/lib/matrix/widgets/boards/henry'

const preset = henryBoard.find(p => p.id === 'home-clock')!

export type MatrixHomeClockProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixHomeClock(props: MatrixHomeClockProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
